             r"|discharge 只用于可达域|能力 .*域|能力 .*重复|能力 .*参数必须"
             r"|能力 .* 的 cyclic 周期|^\d+: 域 .*"
             r"|generation 只用于 revision 域|retire 只用于 revision 域"
