    #   * "只能声明一次" -> "**这一维**只能声明一次"（有两维之后，"哪一维"必须说出来）；
    #   * 多一条"两档不能同时选"（`no_std` + `gc_auto`）。
    # 2026-10-09 `runtime` 维**兑现**（`docs/217`）：这一维从"只声明"变成"有保证"，
    # 多出两条消息，当时**并进 E022 而不是开一个新码** —— 理由是"码按修法分"，
